curl -s "https://datasets-server.huggingface.co/info?dataset=DFKI-SLT/few-nerd" 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
# Navigate the structure
for key in data:
    if key == 'dataset_info':
        for config_name, info in data[key].items():
            if config_name == 'supervised':
                features = info.get('features', [])
                for f in features:
                    if 'fine_ner_tags' in str(f) or 'ner_tags' in str(f):
                        print(json.dumps(f, indent=2))
    else:
        print(f'key: {key}')
" 2>&1 | head -100
